/**
 * Types for the CLI-generated theme module.
 *
 * `astryx-themes.js` is written by `astryx theme add` and regenerated on every
 * theme change, so its shape is declared here rather than patched into it.
 */
import type {DefinedTheme} from '@astryxdesign/core/theme';

export declare const themes: Record<string, DefinedTheme>;
export declare const defaultThemeSlug: string;
